├── src/
│   ├── components/
│   │   ├── LoadingSpinner.tsx  # Loading indicator
│   │   ├── OAuthButton.tsx     # OAuth sign-in buttons
│   │   └── UserCard.tsx        # User profile display
│   ├── context/
│   │   └── AuthContext.tsx     # Auth state management
│   ├── lib/
│   │   └── supabase.ts         # Supabase client initialization
│   ├── pages/
